    ("Catering", "Restauration"),
    ("Druck & Werbung", "Impression et publicité"),
    ("Location", "Lieu / salle"),
    ("Transport & Reisen", "Transport et voyages"),
    ("Technik & Medien", "Technique et médias"),
    ("Merchandising & Textil", "Merchandising et textile"),
    ("Sponsoring", "Sponsoring"),
    ("Versicherung & Recht", "Assurance et droit"),
    ("Sonstiges", "Divers"),
