def kategorien_anlegen(apps, schema_editor):
    kategorie = apps.get_model("partenaires", "PartnerKategorie")
    for nom, nom_fr in KATEGORIEN:
        kategorie.objects.get_or_create(nom=nom, defaults={"nom_fr": nom_fr})


def kategorien_entfernen(apps, schema_editor):
    kategorie = apps.get_model("partenaires", "PartnerKategorie")
    kategorie.objects.filter(nom__in=[nom for nom, _ in KATEGORIEN], partner__isnull=True).delete()


